import java.util.Scanner;

public class Main {
    static final int MAXN = 250010;
    static long[] factorials = new long[MAXN];
    static long[] invFactorials = new long[MAXN];
    static long[][] dynamicDP = new long[30][MAXN];
    static int[] bitsArray = new int[MAXN];

    static long nChoose(int a, int b, long modM) {
        return factorials[a] * invFactorials[a - b] % modM * invFactorials[b] % modM;
    }

    static void addTo(long[] x, int index, long y, long modM) {
        x[index] += y;
        if (x[index] >= modM) x[index] -= modM;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long totalN = sc.nextLong();
        long maxM = sc.nextLong();
        long modM = sc.nextLong();

        factorials[0] = 1;
        invFactorials[0] = 1;
        factorials[1] = 1;
        invFactorials[1] = 1;

        for (int i = 2; i <= totalN; i++) {
            long q = modM / i;
            long r = modM - i * q;
            factorials[i] = factorials[i - 1] * i % modM;
            invFactorials[i] = modM - q * invFactorials[(int) r] % modM;
        }

        for (int i = 2; i <= totalN; i++) {
            invFactorials[i] = invFactorials[i - 1] * invFactorials[i] % modM;
        }

        long answer = 1;
        for (int i = 1; i <= totalN; i++) {
            answer = answer * maxM % modM;
        }

        for (int i = 1; i <= totalN; i++) {
            bitsArray[i] = bitsArray[i >> 1] + (i & 1);
        }

        if (totalN % 2 == 1) {
            System.out.println(answer);
            return;
        }

        dynamicDP[0][0] = 1;
        int maxBitsCount = Math.min(bitsArray[(int) totalN], (int) maxM);

        for (int i = 0; i < maxBitsCount; i++) {
            for (int j = 0; j < totalN; j++) {
                if (dynamicDP[i][j] == 0) continue;
                int mask = (int) (totalN ^ j);
                for (int k = mask; k > j; k = (k - 1) & mask) {
                    int r = k | j;
                    addTo(dynamicDP, i + 1, r, dynamicDP[i][j] * invFactorials[k] % modM, modM);
                }
            }
        }

        for (int i = 1; i <= maxM; i++) {
            long temp = dynamicDP[i][(int) totalN] * factorials[(int) maxM] % modM;
            temp = temp * invFactorials[(int) (maxM - i)] % modM;
            temp = temp * factorials[(int) totalN] % modM;
            answer -= temp;
        }

        answer = (modM + answer % modM) % modM;
        System.out.println(answer);
        sc.close();
    }

    static void addTo(long[][] dp, int i, int j, long value, long modM) {
        dp[i][j] = (dp[i][j] + value) % modM;
    }
